mapper.select:
SELECT i.inquiry_id, i.branch_code, b.name AS branch_name, i.title, i.content, i.category, i.urgency, i.status, DATE_FORMAT(i.created_at, '%Y-%m-%d %H:%i') AS created_at_formatted, DATE_FORMAT(i.updated_at, '%Y-%m-%d %H:%i') AS updated_at_formatted, (SELECT COUNT(*) FROM inquiry_reply ir WHERE ir.inquiry_id = i.inquiry_id) as reply_count FROM inquiry i JOIN branch b ON i.branch_code = b.branch_code WHERE i.branch_code = #{branchCode}
AND i.category = #{category}
AND i.status = #{status}
AND (i.title LIKE CONCAT('%', #{searchTerm}, '%') OR i.content LIKE CONCAT('%', #{searchTerm}, '%'))
ORDER BY i.created_at DESC

mapper.update:
UPDATE inquiry
SET title = #{title}, content = #{content}, category = #{category}, urgency = #{urgency}, updated_at = #{updatedAt}
WHERE inquiry_id = #{inquiryId}
